<?php require '../config.php'; require_admin(); $notice=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='delete'){$id=(int)($_POST['id']??0);$q=db()->prepare('SELECT file_path FROM media WHERE id=?');$q->execute([$id]);$m=$q->fetch();if($m){$p='../'.$m['file_path'];if(is_file($p))@unlink($p);db()->prepare('DELETE FROM media WHERE id=?')->execute([$id]);$notice='Deleted successfully.';}} elseif($action==='toggle'){$id=(int)$_POST['id'];db()->prepare('UPDATE media SET published=1-published WHERE id=?')->execute([$id]);$notice='Publish status updated.';} elseif($action==='upload'){$type=$_POST['type']??'';$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$f=$_FILES['media_file']??null;$allowed=$type==='gallery'?['jpg','jpeg','png','webp']:['mp4','webm','mov','m4v'];$max=$type==='video'?500*1024*1024:15*1024*1024;$ext=$f?strtolower(pathinfo($f['name'],PATHINFO_EXTENSION)):'';$mime=$f&&isset($f['tmp_name'])?(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']):'';$mimeOk=$type==='gallery'?in_array($mime,['image/jpeg','image/png','image/webp'],true):in_array($mime,['video/mp4','video/webm','video/quicktime','video/x-m4v'],true);if(!in_array($type,['gallery','video'],true)||$title===''||!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>$max||!in_array($ext,$allowed,true)||!$mimeOk){$notice='Please choose a valid file and title.';}else{$dir='../uploads/'.$type.'/';if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(16)).'.'.$ext;$path=$dir.$name;if(move_uploaded_file($f['tmp_name'],$path)){db()->prepare('INSERT INTO media(type,title,description,file_path,published) VALUES(?,?,?,?,1)')->execute([$type,$title,$desc,'uploads/'.$type.'/'.$name]);$notice='Uploaded and published. The website updates automatically.';}else $notice='Upload failed. Check hosting upload limits/permissions.';}}}$items=db()->query('SELECT * FROM media ORDER BY created_at DESC')->fetchAll(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Media Manager</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-body"><header class="admin-head"><div class="container admin-nav"><div class="admin-brand"><img src="../assets/images/school-logo.png"><strong>ME’RAJ ADMIN</strong></div><nav><a href="dashboard.php">Dashboard</a><a href="media.php">Media</a><a href="../index.php">Website</a><a href="logout.php">Logout</a></nav></div></header><main class="admin-main"><div class="container"><span class="eyebrow">CONTENT MANAGEMENT</span><h1>Gallery & Video</h1><p>Upload a photo or video here. You do not need to edit HTML, CSS or JavaScript.</p><div class="notice"><?=e($notice)?></div><form class="upload-box" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="upload"><label>Type<select name="type" id="type"><option value="gallery">Gallery Photo</option><option value="video">Video</option></select></label><label>Title<input name="title" required placeholder="e.g. Prize Giving Day"></label><label>Description<textarea name="description" placeholder="Optional"></textarea></label><label>File<input id="file" type="file" name="media_file" required></label><button class="btn" type="submit">Upload & Publish</button></form><div class="table-card"><div class="table-wrap"><table><thead><tr><th>Type</th><th>Title</th><th>Published</th><th>Action</th></tr></thead><tbody><?php foreach($items as $m): ?><tr><td><?=e(ucfirst($m['type']))?></td><td><?=e($m['title'])?></td><td><?=((int)$m['published'])?'Yes':'No'?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-small btn-secondary" name="action" value="toggle">Publish/Hide</button><button class="btn btn-small danger" name="action" value="delete" onclick="return confirm('Delete this item?')">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="4">No media uploaded yet.</td></tr><?php endif; ?></tbody></table></div></div></div></main></body></html>
